#!/usr/bin/env python3
"""Focused regression harness for glib get_tmp_file temporary-name indexing.

The harness extracts the *verbatim* `get_tmp_file` function from a supplied
glib/gfileutils.c (either a working-tree file or a git revision) and compiles
it against minimal stubs with AddressSanitizer.  It then exercises the function
with a matrix of real-time clock values, including negative ones, which is the
condition that makes the signed index used for the `letters[]` array negative.

For the vulnerable (signed) implementation the negative clock cases must make
AddressSanitizer report a global-buffer-overflow; for the fixed (unsigned)
implementation every case must complete cleanly.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

FUNCTION_START = re.compile(r"^static gint\n", re.MULTILINE)
FUNCTION_END = re.compile(r"^\}\n", re.MULTILINE)

STUBS = r"""
#include <errno.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef char gchar;
typedef int gint;
typedef unsigned int guint;
typedef int64_t gint64;
typedef uint64_t guint64;
typedef int gboolean;

#define G_USEC_PER_SEC 1000000

static gint64 stub_now_us = 0;
static gint64 g_get_real_time (void) { return stub_now_us; }

static char *g_strrstr (const char *haystack, const char *needle)
{
  return strstr (haystack, needle);
}

#define g_return_val_if_fail(expr, val) \
  do { if (!(expr)) { fprintf (stderr, "assertion failed: %s\n", #expr); return (val); } } while (0)

typedef gint (*GTmpFileCallback) (const gchar *, gint, gint);

static int record_count = 0;

static gint record_cb (const gchar *filename, gint flags, gint mode)
{
  (void) flags;
  (void) mode;
  (void) filename;
  record_count++;
  errno = EEXIST;
  return -1;
}
"""

MAIN = r"""
int main (int argc, char **argv)
{
  char tmpl[] = "XXXXXX";
  gint rc;

  if (argc != 2)
    {
      fprintf (stderr, "usage: %s <now_us>\n", argv[0]);
      return 2;
    }

  stub_now_us = strtoll (argv[1], NULL, 10);
  errno = 0;
  record_count = 0;
  rc = get_tmp_file (tmpl, record_cb, 0, 0);

  printf ("now_us=%s rc=%d errno=%d tmpl=%s calls=%d\n",
          argv[1], rc, errno, tmpl, record_count);
  return 0;
}
"""


def read_source(args: argparse.Namespace) -> tuple[str, str]:
    if args.source_file:
        path = Path(args.source_file).resolve()
        return path.read_text(encoding="utf-8"), str(path)
    result = subprocess.run(
        ["git", "-C", args.git_repo, "show", f"{args.git_ref}:{args.source}"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if result.returncode != 0:
        raise SystemExit(f"git show failed: {result.stderr.strip()}")
    return result.stdout, f"git:{args.git_repo}:{args.git_ref}:{args.source}"


def extract_function(source: str) -> str:
    match = FUNCTION_START.search(source)
    if not match:
        raise SystemExit("could not locate 'static gint' function start")
    rest = source[match.start():]
    end = FUNCTION_END.search(rest)
    if not end:
        raise SystemExit("could not locate function end")
    text = rest[: end.end()]
    if "get_tmp_file" not in text:
        raise SystemExit("extracted function is not get_tmp_file")
    return text


def build_and_run(source_text: str, label: str, workdir: Path, matrix: list[str]) -> dict:
    function = extract_function(source_text)
    vulnerable = ("guint64 value;" not in function and "guint64 v" not in function)
    harness = (
        STUBS
        + "\n/* --- verbatim get_tmp_file extracted from the supplied source --- */\n"
        + function
        + "\n"
        + MAIN
    )
    c_path = workdir / f"harness_{label}.c"
    bin_path = workdir / f"harness_{label}"
    c_path.write_text(harness, encoding="utf-8")

    compile_cmd = [
        "cc",
        "-O0",
        "-g",
        "-fno-omit-frame-pointer",
        "-fsanitize=address",
        "-o",
        str(bin_path),
        str(c_path),
    ]
    compile_result = subprocess.run(compile_cmd, capture_output=True, text=True, errors="replace")
    if compile_result.returncode != 0:
        raise SystemExit(f"compile failed:\n{compile_result.stderr}")

    runs = []
    for value in matrix:
        env = dict(os.environ)
        env.setdefault("ASAN_OPTIONS", "detect_leaks=0:abort_on_error=1")
        proc = subprocess.run(
            [str(bin_path), value],
            capture_output=True,
            text=True,
            errors="replace",
            env=env,
            timeout=60,
        )
        output = (proc.stdout + proc.stderr).strip()
        runs.append(
            {
                "now_us": value,
                "exit_code": proc.returncode,
                "asan_overflow": "AddressSanitizer" in output and "overflow" in output,
                "stdout": proc.stdout.strip(),
                "stderr_head": "\n".join(proc.stderr.strip().splitlines()[:6]),
            }
        )

    overflow_values = [r["now_us"] for r in runs if r["asan_overflow"]]
    if vulnerable:
        passed = bool(overflow_values) and all(
            r["asan_overflow"] == (r["now_us"].startswith("-")) for r in runs
        )
    else:
        passed = not overflow_values and all(r["exit_code"] == 0 for r in runs)

    return {
        "label": label,
        "implementation": "vulnerable-signed" if vulnerable else "fixed-unsigned",
        "source_sha256": hashlib.sha256(source_text.encode()).hexdigest(),
        "function_sha256": hashlib.sha256(function.encode()).hexdigest(),
        "extracted_function": function,
        "compile_command": compile_cmd,
        "runs": runs,
        "overflow_values": overflow_values,
        "passed": passed,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--git-repo")
    parser.add_argument("--git-ref")
    parser.add_argument("--source", default="glib/gfileutils.c")
    parser.add_argument("--source-file")
    parser.add_argument("--label", default="candidate")
    parser.add_argument("--out-dir")
    parser.add_argument(
        "--matrix",
        default="0,1,1000000,1750000000000000,-1,-1000000,-1750000000000000,-9223372036854775808,9223372036854775807",
    )
    args = parser.parse_args()

    if not args.source_file and not (args.git_repo and args.git_ref):
        raise SystemExit("provide --source-file or --git-repo/--git-ref")

    source_text, source_ref = read_source(args)
    workdir = Path(args.out_dir) if args.out_dir else Path(tempfile.mkdtemp(prefix="tmpname-test-"))
    workdir.mkdir(parents=True, exist_ok=True)

    matrix = [v.strip() for v in args.matrix.split(",") if v.strip()]
    summary = {
        "artifact_type": "focused-get-tmp-file-regression",
        "source_ref": source_ref,
        "matrix": matrix,
        "result": build_and_run(source_text, args.label, workdir, matrix),
        "workdir": str(workdir),
    }
    print(json.dumps(summary, indent=2))
    return 0 if summary["result"]["passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

